Object.assign(SNIP,{});PRESET_NOTES["l19"]={"Ví dụ: Sắp xếp đếm điểm thi": "Không có phép so sánh nào giữa hai phần tử. Lần duyệt đầu đếm, lần duyệt sau đọc mảng đếm theo thứ tự giá trị.", "Ví dụ: sort tăng, giảm và theo tiêu chí riêng": "Hàm so sánh trả về true khi x phải đứng trước y. Ở lần thứ ba: xếp theo chữ số hàng đơn vị, cùng chữ số thì số nhỏ hơn đứng trước.", "Ví dụ: Ổn định và không ổn định": "Sắp xếp mảng chỉ số theo điểm giảm dần. Vì dùng stable_sort, các bạn cùng điểm vẫn giữ thứ tự số báo danh ban đầu: #3 trước #6, #0 trước #2 trước #5.", "Ví dụ: Xếp theo điểm, cùng điểm theo số báo danh": "Ghi rõ tiêu chí phụ trong hàm so sánh thì sort thường cũng cho kết quả xác định, không cần stable_sort."};EX_HINTS["l19"]=[["Mảng đếm toàn cục int cnt[100001] tự bằng 0.", "In cách nhau một khoảng trắng: dùng cờ “đã in số nào chưa” để không có khoảng trắng ở đầu."], ["Tạo vector id gồm 1..n, sắp xếp id bằng hàm so sánh nhìn vào diem.", "Hàm so sánh: điểm khác nhau thì điểm lớn trước; bằng nhau thì số báo danh nhỏ trước. Không dùng >= hay <=."], ["Sắp xếp bản sao b tăng dần. Số người cao điểm hơn hẳn a[i] là số phần tử của b lớn hơn a[i].", "b.end() − upper_bound(b.begin(), b.end(), a[i]) đếm số phần tử > a[i] trong O(log n)."]];
/* ===================== BÀI 19 · Sắp xếp đếm, tính ổn định và hàm sort() của STL ===================== */
/* Bài 19 · Sắp xếp đếm, tính ổn định và hàm sort() của STL
   Sinh bởi công cụ soạn bài: ví dụ cho trình mô phỏng (kèm hình động), bài tập chấm tự động.
   Trắc nghiệm ở quiz.json, gợi ý ở hints.json, lời giải ở solutions/ (nội dung bảo vệ). */
const PR19=[{label:"Ví dụ: Sắp xếp đếm điểm thi",input:"",code:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    vector<int> diem = {7, 3, 9, 7, 10, 3, 7, 5};\n    vector<int> cnt(11, 0);\n    for (int x : diem) cnt[x]++;\n    vector<int> kq;\n    for (int v = 0; v <= 10; v++) {\n        for (int k = 0; k < cnt[v]; k++) kq.push_back(v);\n    }\n    for (int x : kq) cout << x << \" \";\n    cout << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"diem"},{type:"cells",of:"cnt",ptr:["v"],label:"cnt[điểm]"},{type:"cells",of:"kq",label:"kết quả"}],py:{code:"diem = [7, 3, 9, 7, 10, 3, 7, 5]\ncnt = [0] * 11\nfor x in diem:\n    cnt[x] += 1\nkq = []\nfor v in range(11):\n    for k in range(cnt[v]):\n        kq.append(v)\nprint(*kq)"},cs:{code:"using System;\nusing System.Collections.Generic;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] diem = { 7, 3, 9, 7, 10, 3, 7, 5 };\n        int[] cnt = new int[11];\n        foreach (int x in diem) cnt[x]++;\n        List<int> kq = new List<int>();\n        for (int v = 0; v <= 10; v++)\n        {\n            for (int k = 0; k < cnt[v]; k++) kq.Add(v);\n        }\n        Console.WriteLine(string.Join(\" \", kq));\n    }\n}"}},{label:"Ví dụ: sort tăng, giảm và theo tiêu chí riêng",input:"",code:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nbool theoChuSoCuoi(int x, int y) {\n    if (x % 10 != y % 10) return x % 10 < y % 10;\n    return x < y;\n}\n\nint main() {\n    vector<int> a = {42, 17, 93, 8, 61, 35, 27};\n    sort(a.begin(), a.end());\n    for (int x : a) cout << x << \" \";\n    cout << \"\\n\";\n    sort(a.begin(), a.end(), greater<int>());\n    for (int x : a) cout << x << \" \";\n    cout << \"\\n\";\n    sort(a.begin(), a.end(), theoChuSoCuoi);\n    for (int x : a) cout << x << \" \";\n    cout << \"\\n\";\n    return 0;\n}",viz:[{type:"bars",of:"a"}],py:{label:"Ví dụ: sort tăng, giảm và theo khóa (key)",code:"a = [42, 17, 93, 8, 61, 35, 27]\na.sort()\nprint(*a)\na.sort(reverse=True)\nprint(*a)\na.sort(key=lambda x: (x % 10, x))\nprint(*a)",note:"key cho biết sắp xếp theo giá trị nào của mỗi phần tử. Ở lần thứ ba, khóa là cặp (chữ số hàng đơn vị, chính số đó): so chữ số đơn vị trước, bằng nhau thì so số."},cs:{label:"Ví dụ: Array.Sort tăng, giảm và theo tiêu chí riêng",code:"using System;\n\nclass Program\n{\n    static int TheoChuSoCuoi(int x, int y)\n    {\n        if (x % 10 != y % 10) return (x % 10).CompareTo(y % 10);\n        return x.CompareTo(y);\n    }\n\n    static void Main()\n    {\n        int[] a = { 42, 17, 93, 8, 61, 35, 27 };\n        Array.Sort(a);\n        Console.WriteLine(string.Join(\" \", a));\n        Array.Sort(a, (x, y) => y.CompareTo(x));\n        Console.WriteLine(string.Join(\" \", a));\n        Array.Sort(a, TheoChuSoCuoi);\n        Console.WriteLine(string.Join(\" \", a));\n    }\n}",note:"Hàm so sánh của C# trả về một số nguyên: âm nếu x đứng trước y, dương nếu y đứng trước x, 0 nếu ngang nhau. x.CompareTo(y) cho đúng ba giá trị đó; đổi chỗ thành y.CompareTo(x) để xếp giảm dần."}},{label:"Ví dụ: Ổn định và không ổn định",input:"",code:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint diem[8] = {8, 6, 8, 9, 6, 8, 9, 6};\n\nbool theoDiem(int x, int y) {\n    return diem[x] > diem[y];      // chỉ so điểm, giảm dần\n}\n\nint main() {\n    vector<int> id = {0, 1, 2, 3, 4, 5, 6, 7};\n    stable_sort(id.begin(), id.end(), theoDiem);\n    for (int i : id) cout << \"#\" << i << \"(\" << diem[i] << \") \";\n    cout << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"id",label:"id (thứ tự sau khi xếp)"}],py:{code:"diem = [8, 6, 8, 9, 6, 8, 9, 6]\nid = list(range(8))\nid.sort(key=lambda i: -diem[i])     # chỉ so điểm, giảm dần\nprint(*[f\"#{i}({diem[i]})\" for i in id])",viz:[{type:"cells",of:"id",label:"id (thứ tự sau khi xếp)"}],note:"Sắp xếp của Python luôn ổn định: các bạn cùng điểm vẫn giữ thứ tự số báo danh ban đầu (#3 trước #6, #0 trước #2 trước #5) dù khóa chỉ là điểm."},cs:{code:"using System;\nusing System.Linq;\n\nclass Program\n{\n    static int[] diem = { 8, 6, 8, 9, 6, 8, 9, 6, 7, 8, 6, 9, 7, 8, 6, 9, 7, 8, 6, 7 };\n\n    static void Main()\n    {\n        int n = diem.Length;\n        int[] id = new int[n];\n        for (int i = 0; i < n; i++) id[i] = i;\n        int[] a = (int[])id.Clone();\n        Array.Sort(a, (x, y) => diem[y].CompareTo(diem[x]));   // không ổn định\n        Console.WriteLine(\"Array.Sort: \" + string.Join(\" \", a));\n        int[] b = id.OrderByDescending(i => diem[i]).ToArray();   // ổn định\n        Console.WriteLine(\"OrderBy:    \" + string.Join(\" \", b));\n    }\n}",viz:[{type:"cells",of:"b",label:"b (OrderBy, ổn định)"}],note:"Cả hai cách chỉ so điểm, giảm dần. Array.Sort (introsort) không giữ thứ tự ban đầu của những người cùng điểm: hàng 9 điểm ra 15 3 11 6. OrderByDescending của LINQ ổn định: cùng điểm thì vẫn theo số thứ tự ban đầu 3 6 11 15. Với ít hơn 17 phần tử, Array.Sort dùng sắp xếp chèn nên tình cờ vẫn ổn định; đừng dựa vào điều đó."}},{label:"Ví dụ: Xếp theo điểm, cùng điểm theo số báo danh",input:"",code:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint diem[6] = {7, 9, 7, 10, 9, 7};\n\nbool truoc(int x, int y) {\n    if (diem[x] != diem[y]) return diem[x] > diem[y];\n    return x < y;\n}\n\nint main() {\n    vector<int> id = {0, 1, 2, 3, 4, 5};\n    sort(id.begin(), id.end(), truoc);\n    for (int i : id) cout << \"SBD \" << i << \": \" << diem[i] << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"id"}],py:{code:"diem = [7, 9, 7, 10, 9, 7]\nid = list(range(6))\nid.sort(key=lambda i: (-diem[i], i))\nfor i in id:\n    print(\"SBD\", str(i) + \":\", diem[i])",note:"Khóa là cặp (−điểm, số báo danh): điểm cao đứng trước, cùng điểm thì số báo danh nhỏ đứng trước."},cs:{code:"using System;\n\nclass Program\n{\n    static int[] diem = { 7, 9, 7, 10, 9, 7 };\n\n    static int Truoc(int x, int y)\n    {\n        if (diem[x] != diem[y]) return diem[y].CompareTo(diem[x]);   // điểm giảm\n        return x.CompareTo(y);                                       // số báo danh tăng\n    }\n\n    static void Main()\n    {\n        int[] id = { 0, 1, 2, 3, 4, 5 };\n        Array.Sort(id, Truoc);\n        foreach (int i in id) Console.WriteLine(\"SBD \" + i + \": \" + diem[i]);\n    }\n}"}}];
