makeEx2(document.getElementById("ex-l19"),sim19,[{t:"Sắp xếp đếm",d:"Đầu vào: n (1 ≤ n ≤ 10^5) rồi n số nguyên trong khoảng 0..100000. Đầu ra: dãy xếp tăng dần. Hãy dùng sắp xếp đếm (không dùng sort).",tests:[{in:"8\n7 3 9 7 10 3 7 5",out:"3 3 5 7 7 7 9 10"},{in:"1\n0",out:"0"},{in:"4\n100000 0 100000 1",out:"0 1 100000 100000"}],start:"#include <iostream>\nusing namespace std;\n\nint cnt[100001];\n\nint main() {\n    int n;\n    cin >> n;\n    // đếm, rồi in theo thứ tự giá trị\n    return 0;\n}",need:/^(?![\s\S]*\bsort\s*\()/,needMsg:"Bài này luyện sắp xếp đếm: hãy làm mà không dùng sort.",perf:{gen:n=>n+"\n"+Array.from({length:n},(_,i)=>(i*7919)%100001).join(" "),ns:[500,2000,8000],need:"n",limit:n=>40*n+500000,why:"Sắp xếp O(n²) quá chậm. Sắp xếp đếm chỉ tốn O(n + V)."},py:{start:"n = int(input())\na = list(map(int, input().split()))\n# đếm, rồi in theo thứ tự giá trị",hints:["Danh sách đếm cnt = [0] * 100001.","Đi qua v từ nhỏ tới lớn, thêm v vào kết quả cnt[v] lần, rồi in bằng print(*kq)."],needMsg:"Bài này luyện sắp xếp đếm: hãy làm mà không dùng sort hay sorted.",need:/^(?![\s\S]*\bsort(ed)?\s*\()/},cs:{start:"using System;\nusing System.Text;\n\nclass Program\n{\n    static void Main()\n    {\n        int n = int.Parse(Console.ReadLine());\n        int[] a = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        int[] cnt = new int[100001];\n        // đếm, rồi in theo thứ tự giá trị\n    }\n}",hints:["Mảng đếm new int[100001] tự bằng 0.","Gom kết quả vào StringBuilder; thêm khoảng trắng trước mỗi số trừ số đầu tiên."],needMsg:"Hãy dùng sắp xếp đếm (mảng cnt), không dùng Array.Sort, List.Sort hay OrderBy.",need:/^(?![\s\S]*\b(Sort|OrderBy|OrderByDescending)\s*\()/}},{t:"Bảng xếp hạng",d:"Đầu vào: n (1 ≤ n ≤ 10^5) rồi n số nguyên: điểm của học sinh có số báo danh 1..n (0 ≤ điểm ≤ 10^9). Đầu ra: n dòng, mỗi dòng “số báo danh điểm”, xếp theo điểm giảm dần; cùng điểm thì số báo danh nhỏ hơn đứng trước.",tests:[{in:"6\n7 9 7 10 9 7",out:"4 10\n2 9\n5 9\n1 7\n3 7\n6 7"},{in:"1\n5",out:"1 5"},{in:"3\n0 0 1000000000",out:"3 1000000000\n1 0\n2 0"}],start:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint diem[100001];\n\nint main() {\n    int n;\n    cin >> n;\n    for (int i = 1; i <= n; i++) cin >> diem[i];\n    // sắp xếp mảng số báo danh bằng hàm so sánh\n    return 0;\n}",perf:{gen:n=>n+"\n"+Array.from({length:n},(_,i)=>(i*7919)%101).join(" "),ns:[250,500,1000,2000],need:"nlogn",limit:n=>90*n*Math.log2(n)+200,why:"Mỗi lần tìm học sinh điểm cao nhất còn lại là O(n²). Dùng sort với hàm so sánh."},py:{start:"n = int(input())\ndiem = [0] + list(map(int, input().split()))\n# sắp xếp danh sách số báo danh theo khóa",hints:["Tạo id = list(range(1, n + 1)) rồi sắp xếp id.","Khóa (−diem[i], i): điểm lớn trước; bằng nhau thì số báo danh nhỏ trước."]},cs:{start:"using System;\nusing System.Text;\n\nclass Program\n{\n    static int[] diem;\n\n    static void Main()\n    {\n        int n = int.Parse(Console.ReadLine());\n        int[] d = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        diem = new int[n + 1];\n        for (int i = 1; i <= n; i++) diem[i] = d[i - 1];\n        // sắp xếp mảng số báo danh bằng hàm so sánh\n    }\n}",hints:["Tạo mảng id gồm 1..n, sắp xếp id bằng hàm so sánh nhìn vào diem (khai báo static để hàm so sánh dùng được).","Hàm so sánh: điểm khác nhau thì điểm lớn trước (diem[y].CompareTo(diem[x])); bằng nhau thì số báo danh nhỏ trước (x.CompareTo(y))."]}},{t:"Thứ hạng",d:"Đầu vào: n (1 ≤ n ≤ 10^5) rồi n số nguyên (0 ≤ aᵢ ≤ 10^9): điểm của từng người theo thứ tự. Thứ hạng của một người bằng 1 cộng số người có điểm cao hơn hẳn. Đầu ra: thứ hạng của từng người theo thứ tự ban đầu, cách nhau một khoảng trắng.",tests:[{in:"6\n7 9 7 10 9 7",out:"4 2 4 1 2 4"},{in:"1\n0",out:"1"},{in:"4\n5 5 5 5",out:"1 1 1 1"},{in:"3\n1 2 3",out:"3 2 1"}],start:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> a(n);\n    for (int i = 0; i < n; i++) cin >> a[i];\n    // sắp xếp một bản sao, đếm số người cao điểm hơn bằng tìm kiếm nhị phân\n    return 0;\n}",perf:{gen:n=>n+"\n"+Array.from({length:n},(_,i)=>(i*7919)%1000).join(" "),ns:[250,500,1000,2000],need:"nlogn",limit:n=>70*n*Math.log2(n)+200,why:"So từng cặp người là O(n²). Sắp xếp một lần rồi tìm kiếm nhị phân cho mỗi người."},py:{start:"from bisect import bisect_right\nn = int(input())\na = list(map(int, input().split()))\n# sắp xếp một bản sao, đếm số người cao điểm hơn bằng tìm kiếm nhị phân",hints:["b = sorted(a) tạo bản sao đã sắp xếp. Số người cao điểm hơn hẳn x là số phần tử của b lớn hơn x.","len(b) − bisect_right(b, x) đếm số phần tử > x trong O(log n)."]},cs:{start:"using System;\nusing System.Text;\n\nclass Program\n{\n    static void Main()\n    {\n        int n = int.Parse(Console.ReadLine());\n        int[] a = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        // sắp xếp một bản sao, đếm số người cao điểm hơn bằng tìm kiếm nhị phân\n    }\n}",hints:["Sắp xếp bản sao b tăng dần ((int[])a.Clone() tạo bản sao). Số người cao điểm hơn hẳn a[i] là số phần tử của b lớn hơn a[i].","n − UpperBound(b, a[i]) đếm số phần tử > a[i] trong O(log n) (hàm UpperBound tự viết như Bài 14)."]}}]);

makeQuiz("quiz19","score19",[{"q": "Sắp xếp đếm n số trong khoảng 0..V tốn?", "o": ["O(n log n)", "O(n + V)", "O(n · V)", "O(V log V)"], "a": 1, "e": "Một lần đếm O(n), một lần đọc mảng đếm O(V + n)."}, {"q": "Sắp xếp ổn định nghĩa là?", "o": ["Luôn O(n log n)", "Không dùng bộ nhớ phụ", "Các phần tử có khóa bằng nhau giữ nguyên thứ tự ban đầu", "Không bao giờ bị lỗi"], "a": 2, "e": "Ví dụ hai bạn cùng 9 điểm, bạn đứng trước trong danh sách gốc vẫn đứng trước sau khi xếp."}, {"q": "Hàm so sánh nào ĐÚNG để sort giảm dần?", "o": ["return x >= y;", "return x > y;", "return x < y;", "return x != y;"], "a": 1, "e": "Phải là quan hệ “hơn hẳn”: so sánh một số với chính nó phải trả về false.", "lang": ["cpp"]}, {"q": "Hàm sort của STL có ổn định không?", "o": ["Có", "Không, cần ổn định thì dùng stable_sort", "Chỉ với số nguyên", "Chỉ khi có greater<int>()"], "a": 1, "e": "sort là introsort (dựa trên sắp xếp nhanh), không ổn định.", "lang": ["cpp"]}, {"q": "Vì sao sắp xếp đếm “vượt qua” được giới hạn n log n?", "o": ["Vì dùng đệ quy", "Vì không so sánh hai phần tử mà dùng giá trị làm chỉ số", "Vì dùng mảng phụ", "Vì chạy song song"], "a": 1, "e": "Giới hạn n log n chỉ áp dụng cho thuật toán dựa trên so sánh."}, {"q": "Sắp xếp học sinh theo điểm giảm dần, cùng điểm thì tên tăng dần. Khóa nào đúng?", "o": ["key=lambda s: (s.diem, s.ten)", "key=lambda s: (-s.diem, s.ten)", "key=lambda s: -s.diem", "reverse=True"], "a": 1, "e": "Đổi dấu điểm để điểm cao đứng trước; tên để nguyên nên tăng dần.", "lang": ["py"]}, {"q": "list.sort() của Python có ổn định không?", "o": ["Có", "Không", "Chỉ với số nguyên", "Chỉ khi reverse=True"], "a": 0, "e": "Timsort luôn ổn định: phần tử có khóa bằng nhau giữ thứ tự ban đầu.", "lang": ["py"]}, {"q": "Hàm so sánh nào ĐÚNG để Array.Sort xếp giảm dần?", "o": ["(x, y) =&gt; x.CompareTo(y)", "(x, y) =&gt; y.CompareTo(x)", "(x, y) =&gt; x &gt; y ? 1 : 0", "(x, y) =&gt; x &gt;= y ? -1 : 1"], "a": 1, "e": "y.CompareTo(x) âm khi x lớn hơn y, nên số lớn đứng trước. Hai cách cuối không nhất quán (x với chính nó không cho 0, hoặc không bao giờ cho số âm).", "lang": ["cs"]}, {"q": "Array.Sort của C# có ổn định không?", "o": ["Có", "Không; cần ổn định thì dùng OrderBy của LINQ", "Chỉ với số nguyên", "Chỉ khi truyền hàm so sánh"], "a": 1, "e": "Array.Sort dùng introsort nên không ổn định. OrderBy / ThenBy của LINQ thì ổn định.", "lang": ["cs"]}]);

